findings.codeql_raw_query:
/**
 * @name ReDoS - user controlled regex pattern
 * @description Find re.compile/search/match/fullmatch calls where pattern may be user controlled
 * @kind problem
 * @problem.severity warning
 * @id custom/py/redos-pattern-flow
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module ReDoSConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("re").getMember(["compile", "search", "match", "fullmatch", "findall", "finditer"]).getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module ReDoSFlow = TaintTracking::Global<ReDoSConfig>;

from DataFlow::Node source, DataFlow::Node sink
where ReDoSFlow::flow(source, sink)
select sink, "Regex pattern derived from $@.", source, "untrusted input"
